import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor conv_transpose2d_launch(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups);

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
    return conv_transpose2d_launch(
        x, weight, bias,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w,
        groups);
}
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_pipeline.h>
__global__ void conv_transpose2d_gather_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int Cin, int H, int W,
    int Cout, int Ho, int Wo,
    int KH, int KW,
    int sh, int sw_,
    int ph, int pw,
    int dh, int dw,
    int groups) {
    extern __shared__ float smem[];
    constexpr int TH = 2;
    constexpr int TW = 2;
    constexpr int TILE_H = 16 * TH;
    constexpr int TILE_W = 16 * TW;
    const int out_per_group = Cout / groups;
    const int in_per_group = Cin / groups;
    const int opg_pad = (out_per_group + 3) & ~3;
    const int g = blockIdx.z % groups;
    const int n = blockIdx.z / groups;
    const int ci0 = g * in_per_group;
    const int co0 = g * out_per_group;
    const int wo0 = blockIdx.x * blockDim.x * TW;
    const int ho0 = blockIdx.y * blockDim.y * TH;
    const int kwk = KH * KW;
    const int hnum_min = ho0 + ph - (KH - 1) * dh;
    const int hnum_max = ho0 + (int)blockDim.y * TH - 1 + ph;
    const int wnum_min = wo0 + pw - (KW - 1) * dw;
    const int wnum_max = wo0 + (int)blockDim.x * TW - 1 + pw;
    int hi_lo = hnum_min / sh;
    if (hi_lo < 0) hi_lo = 0;
    int hi_hi = hnum_max / sh;
    if (hi_hi > H - 1) hi_hi = H - 1;
    int wi_lo = wnum_min / sw_;
    if (wi_lo < 0) wi_lo = 0;
    int wi_hi = wnum_max / sw_;
    if (wi_hi > W - 1) wi_hi = W - 1;
    if (hi_lo > hi_hi) hi_lo = hi_hi;
    if (wi_lo > wi_hi) wi_lo = wi_hi;
    const int SH = hi_hi - hi_lo + 1;
    const int SW = wi_hi - wi_lo + 1;
    float* sx = smem;
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;
    const int nthreads = blockDim.x * blockDim.y;
    const int xcount = in_per_group * SH * SW;
    const int xcount_pad = (xcount + 3) & ~3;
    float* sw = smem + xcount_pad;
    const int wcount = out_per_group * in_per_group * kwk;
    const int wstore_count = in_per_group * kwk * opg_pad;
    int* shmap = reinterpret_cast<int*>(sw + wstore_count);
    int* swmap = shmap + KH * TILE_H;
    const long long xbase = ((long long)n * Cin + ci0) * H * W;
#if __CUDA_ARCH__ >= 800
    for (int e = tid; e < xcount; e += nthreads) {
        const int c = e / (SH * SW);
        const int rem = e - c * SH * SW;
        const int shh = rem / SW;
        const int sww = rem - shh * SW;
        __pipeline_memcpy_async(sx + e, x + xbase + ((long long)c * H + (hi_lo + shh)) * W + (wi_lo + sww), sizeof(float));
    }
    for (int e = tid; e < wcount; e += nthreads) {
        const int co_local = e / (in_per_group * kwk);
        const int crem = e - co_local * in_per_group * kwk;
        const int c = crem / kwk;
        const int krem = crem - c * kwk;
        __pipeline_memcpy_async(sw + (c * kwk + krem) * opg_pad + co_local, w + ((long long)(ci0 + c) * out_per_group + co_local) * kwk + krem, sizeof(float));
    }
    __pipeline_commit();
    __pipeline_wait_prior(0);
#else
    for (int e = tid; e < xcount; e += nthreads) {
        const int c = e / (SH * SW);
        const int rem = e - c * SH * SW;
        const int shh = rem / SW;
        const int sww = rem - shh * SW;
        sx[e] = __ldg(x + xbase + ((long long)c * H + (hi_lo + shh)) * W + (wi_lo + sww));
    }
    for (int e = tid; e < wcount; e += nthreads) {
        const int co_local = e / (in_per_group * kwk);
        const int crem = e - co_local * in_per_group * kwk;
        const int c = crem / kwk;
        const int krem = crem - c * kwk;
        sw[(c * kwk + krem) * opg_pad + co_local] = __ldg(w + ((long long)(ci0 + c) * out_per_group + co_local) * kwk + krem);
    }
#endif
    for (int e = tid; e < KH * TILE_H; e += nthreads) {
        const int kh = e / TILE_H;
        const int hl = e - kh * TILE_H;
        const int hnum = ho0 + hl + ph - kh * dh;
        int mapped = -1;
        if (hnum >= 0) {
            const int hi = hnum / sh;
            if (hnum - hi * sh == 0 && hi < H) mapped = hi - hi_lo;
        }
        shmap[e] = mapped;
    }
    for (int e = tid; e < KW * TILE_W; e += nthreads) {
        const int kw = e / TILE_W;
        const int wl = e - kw * TILE_W;
        const int wnum = wo0 + wl + pw - kw * dw;
        int mapped = -1;
        if (wnum >= 0) {
            const int wi = wnum / sw_;
            if (wnum - wi * sw_ == 0 && wi < W) mapped = wi - wi_lo;
        }
        swmap[e] = mapped;
    }
    __syncthreads();
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    constexpr int RB = 4;
    int co_local = 0;
    for (; co_local + RB <= out_per_group; co_local += RB) {
        float acc[RB][TH][TW];
        #pragma unroll
        for (int r = 0; r < RB; ++r) {
            #pragma unroll
            for (int th = 0; th < TH; ++th) {
                #pragma unroll
                for (int tw = 0; tw < TW; ++tw) {
                    acc[r][th][tw] = 0.0f;
                }
            }
        }
        for (int kh = 0; kh < KH; ++kh) {
            int shi_[TH];
            const int* hm = shmap + kh * TILE_H + ty;
            #pragma unroll
            for (int th = 0; th < TH; ++th) {
                shi_[th] = hm[th * (int)blockDim.y];
            }
            for (int kw = 0; kw < KW; ++kw) {
                int swi_[TW];
                const int* wm = swmap + kw * TILE_W + tx;
                #pragma unroll
                for (int tw = 0; tw < TW; ++tw) {
                    swi_[tw] = wm[tw * (int)blockDim.x];
                }
                for (int c = 0; c < in_per_group; ++c) {
                    const float* xr = sx + c * SH * SW;
                    float xv[TH][TW];
                    #pragma unroll
                    for (int th = 0; th < TH; ++th) {
                        #pragma unroll
                        for (int tw = 0; tw < TW; ++tw) {
                            xv[th][tw] = (shi_[th] >= 0 && swi_[tw] >= 0) ? xr[shi_[th] * SW + swi_[tw]] : 0.0f;
                        }
                    }
                    const float4 wv4 = *reinterpret_cast<const float4*>(sw + (c * kwk + kh * KW + kw) * opg_pad + co_local);
                    #pragma unroll
                    for (int r = 0; r < RB; ++r) {
                        const float wv = (r == 0) ? wv4.x : ((r == 1) ? wv4.y : ((r == 2) ? wv4.z : wv4.w));
                        #pragma unroll
                        for (int th = 0; th < TH; ++th) {
                            #pragma unroll
                            for (int tw = 0; tw < TW; ++tw) {
                                acc[r][th][tw] += xv[th][tw] * wv;
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int r = 0; r < RB; ++r) {
            const int co = co0 + co_local + r;
            const float bv = (b != nullptr) ? __ldg(b + co) : 0.0f;
            #pragma unroll
            for (int th = 0; th < TH; ++th) {
                const int ho = ho0 + ty + th * (int)blockDim.y;
                if (ho >= Ho) continue;
                #pragma unroll
                for (int tw = 0; tw < TW; ++tw) {
                    const int wo = wo0 + tx + tw * (int)blockDim.x;
                    if (wo >= Wo) continue;
                    y[((long long)(n * Cout + co) * Ho + ho) * Wo + wo] = acc[r][th][tw] + bv;
                }
            }
        }
    }
    for (; co_local < out_per_group; ++co_local) {
        float acc[TH][TW];
        #pragma unroll
        for (int th = 0; th < TH; ++th) {
            #pragma unroll
            for (int tw = 0; tw < TW; ++tw) {
                acc[th][tw] = 0.0f;
            }
        }
        for (int kh = 0; kh < KH; ++kh) {
            int shi_[TH];
            const int* hm = shmap + kh * TILE_H + ty;
            #pragma unroll
            for (int th = 0; th < TH; ++th) {
                shi_[th] = hm[th * (int)blockDim.y];
            }
            for (int kw = 0; kw < KW; ++kw) {
                int swi_[TW];
                const int* wm = swmap + kw * TILE_W + tx;
                #pragma unroll
                for (int tw = 0; tw < TW; ++tw) {
                    swi_[tw] = wm[tw * (int)blockDim.x];
                }
                for (int c = 0; c < in_per_group; ++c) {
                    const float* xr = sx + c * SH * SW;
                    const float wv = sw[(c * kwk + kh * KW + kw) * opg_pad + co_local];
                    #pragma unroll
                    for (int th = 0; th < TH; ++th) {
                        #pragma unroll
                        for (int tw = 0; tw < TW; ++tw) {
                            if (shi_[th] >= 0 && swi_[tw] >= 0) acc[th][tw] += xr[shi_[th] * SW + swi_[tw]] * wv;
                        }
                    }
                }
            }
        }
        const int co = co0 + co_local;
        const float bv = (b != nullptr) ? __ldg(b + co) : 0.0f;
        #pragma unroll
        for (int th = 0; th < TH; ++th) {
            const int ho = ho0 + ty + th * (int)blockDim.y;
            if (ho >= Ho) continue;
            #pragma unroll
            for (int tw = 0; tw < TW; ++tw) {
                const int wo = wo0 + tx + tw * (int)blockDim.x;
                if (wo >= Wo) continue;
                y[((long long)(n * Cout + co) * Ho + ho) * Wo + wo] = acc[th][tw] + bv;
            }
        }
    }
}
torch::Tensor conv_transpose2d_launch(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    const at::cuda::CUDAGuard guard(x.device());
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    torch::Tensor bc = bias;
    const bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
        bc = bias.contiguous();
    }
    const int N = (int)xc.size(0);
    const int Cin = (int)xc.size(1);
    const int H = (int)xc.size(2);
    const int W = (int)xc.size(3);
    const int KH = (int)wc.size(2);
    const int KW = (int)wc.size(3);
    const int in_per_group = Cin / (int)groups;
    TORCH_CHECK(wc.size(0) == Cin, "weight in_channels mismatch");
    TORCH_CHECK(Cin % (int)groups == 0, "Cin must be divisible by groups");
    const int out_per_group = (int)wc.size(1);
    const int Cout_real = out_per_group * (int)groups;
    if (has_bias) TORCH_CHECK(bc.numel() == Cout_real, "bias size mismatch");
    const int Ho = (int)((H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1);
    const int Wo = (int)((W - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1);
    TORCH_CHECK(Ho > 0 && Wo > 0, "invalid output size");
    auto y = at::empty({N, Cout_real, Ho, Wo}, xc.options());
    dim3 block(16, 16, 1);
    const int tiles_w = (Wo + 16 * 2 - 1) / (16 * 2);
    const int tiles_h = (Ho + 16 * 2 - 1) / (16 * 2);
    dim3 grid(tiles_w, tiles_h, N * (int)groups);
    const int sh_max = (16 * 2 - 1 + (KH - 1) * (int)dil_h) / (int)stride_h + 2;
    const int sw_max = (16 * 2 - 1 + (KW - 1) * (int)dil_w) / (int)stride_w + 2;
    const int out_per_group_pad = (out_per_group + 3) & ~3;
    const size_t x_smem = (((size_t)in_per_group * sh_max * sw_max + 3) / 4) * 4;
    const size_t map_elems = ((size_t)KH + (size_t)KW) * 16 * 2;
    const size_t smem_bytes = (x_smem + (size_t)out_per_group_pad * in_per_group * KH * KW) * sizeof(float) + map_elems * sizeof(int);
    TORCH_CHECK(smem_bytes <= 48 * 1024, "shared memory tile too large");
    auto stream = at::cuda::getCurrentCUDAStream();
    conv_transpose2d_gather_kernel<<<grid, block, smem_bytes, stream>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        has_bias ? bc.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        N, Cin, H, W,
        Cout_real, Ho, Wo,
        KH, KW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        (int)groups);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_conv_transpose_ext = load_inline(
    name="conv_transpose2d_gather_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv_transpose2d_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose2d.weight
        bias = self.conv_transpose2d.bias
        if bias is None:
            bias = x.new_empty(0)
        return _conv_transpose_ext.conv_transpose2d_cuda(
            x,
            weight,
            bias,
            self.stride[0],
            self.stride[1],
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
            self.groups,
        )

